# A7 11.01  Equations with Like Terms and the Distributive Property — MA.8.AR.2.1 (MN 11.1). Mon 30 Nov 2026,
# the unit's first day, after Thanksgiving week. The two-step equations of Unit 1 (px + q = r, p(x + q) = r) grow a
# step: like terms are collected first, and a factor outside parentheses multiplies EVERY term inside — including a
# subtracted group, where the −3 reaches the −2 and makes +6. The variable is on one side only (both sides is 11.02;
# the three endings are 11.03). Built from the benchmark and the B1G-M first (the unit's Lesson Outlines, §11.01),
# then read against Math Nation 11.1 (the unit audit). Not reproduced: the book's collaboration video warm-up, its
# partner tasks, Kenneth's like-terms error whose wrong move lands on the right answer (audit D1), Elena's key that
# names a legal move as the error (D2), and the coins item whose variable is not what is asked (D3).
#
# Every equation is solved again by sympy at build time: root() below solves "left = right" for a REAL unknown
# (the build's own letters are positive symbols), so no answer here leans on the sign of the variable.

U = "sp.Symbol('u', real=True)"


def _u(e):
    import re
    return re.sub(r"\bu\b", U, e)


def solves(left, right, value):
    """sympy solves left = right (in u) and finds exactly `value`."""
    return ("eq", "sp.solve(sp.Eq(" + _u(left) + ", " + _u(right) + "), " + U + ")[0]", value)


def same(e1, e2):
    """Two expressions in u are the same expression (a correct line of work)."""
    return ("true", "sp.expand(" + _u(e1) + " - (" + _u(e2) + ")) == 0")


def differs(e1, e2):
    """Two expressions in u are NOT the same expression (a wrong line of work)."""
    return ("true", "sp.expand(" + _u(e1) + " - (" + _u(e2) + ")) != 0")


def not_root(left, right, value):
    """`value` does not solve left = right (in u)."""
    return ("true", "sp.solve(sp.Eq(" + _u(left) + ", " + _u(right) + "), " + U + ") != [" + value + "]")


